insert into public.interactive_assignment_templates(slug,day,title,target_slugs,is_lab) values ('day-9-foundation-inertia',9,'Day 9 · Foundation: Newton’s first law and inertia',array['u1.newtons-first-law-inertia'],false);
insert into public.daily_lesson_templates(key,foundation_slug,review_slug,foundation_questions,review_questions,quiz) values ('unit-1-day-9','day-9-foundation-inertia','day-9-inertia',array['f9-balanced','f9-recall','f9-law','f9-demo','f9-balance','f9-passenger','f9-asteroid','f9-test','f9-exit-deflect','f9-exit-transfer'],array['r2-1a','r2-1b','r2-1c','r2-2a','r2-2b','r2-2c','r2-3a','r2-3b','r2-4a','r2-4b','r2-5a','r2-5b'],'{"title":"Day 9 · Quiz: Newton’s first law and inertia","instructions":"Work independently after submitting the foundation and review. Identify the object and reference frame, name interactions and distinguish velocity from changes in velocity. Your teacher releases the quiz grade and reviews mastery separately.","questions":[{"kind":"choice","prompt":"A spacecraft moves left at 6 m/s in an inertial frame. Its net external force remains zero. What happens?","options":["It slows until it stops","It keeps moving left at 6 m/s","It turns right","Its inertia creates thrust"],"correct_index":1,"guide":"Zero net force preserves the existing velocity, including its direction.","points":1,"demand":{"blooms":"Understand","dok":1,"evidence":"Applies the first law to nonzero initial velocity."}},{"kind":"choice","prompt":"A crate moves right at constant velocity. A rope pulls 12 N right and friction acts 12 N left. What is the net horizontal force?","options":["24 N right","12 N left","0 N","12 N right"],"correct_index":2,"guide":"With right positive, +12−12 = 0 N. Balanced forces permit constant nonzero velocity.","points":1,"demand":{"blooms":"Apply","dok":1,"evidence":"Adds opposing forces on one moving object."}},{"kind":"choice","prompt":"A 1 kg cart and a 4 kg cart experience the same nonzero net force. Which statement is correct?","options":["The 4 kg cart has greater inertia and less acceleration","The 4 kg cart must already have less speed","The 1 kg cart needs a force to maintain constant velocity","Inertia supplies an extra opposing force"],"correct_index":0,"guide":"Mass measures inertia. Under the same net force, greater mass means less acceleration, not a predetermined velocity.","points":1,"demand":{"blooms":"Understand","dok":1,"evidence":"Distinguishes inertia and acceleration from current speed."}},{"kind":"choice","prompt":"A probe follows a curved path at constant speed. What can you conclude in an inertial frame?","options":["Its velocity is constant","Its net force must be zero","No interaction can be acting","Its velocity changes direction, so its net force is nonzero"],"correct_index":3,"guide":"Constant speed does not imply constant velocity; turning requires acceleration and a nonzero net force.","points":1,"demand":{"blooms":"Analyze","dok":2,"evidence":"Uses changing direction to distinguish speed, velocity and net force."}},{"kind":"written","prompt":"A train moving forward brakes. In the ground frame, a passenger initially continues forward until the seat or restraint slows them. Explain the passenger’s motion and the force that changes it. Compare this with a quickly removed card: why can a coin gain little horizontal speed yet fall downward?","guide":"Passenger initially retains forward velocity; no new forward inertia force is required. A backward interaction from a restraint/seat changes the passenger’s velocity. For the coin, friction acts briefly so horizontal velocity changes little; after support is removed gravity causes downward acceleration. Credit correct first-law reasoning, named interactions in each case and separation of horizontal/vertical or ground/relative motion. Inertia is a property, not an extra force.","points":3,"demand":{"blooms":"Analyze","dok":2,"evidence":"Transfers interaction-based explanations across a passenger and a coin demonstration."}},{"kind":"written","prompt":"A student says, “After an engine switches off, a probe travels straight forever because space has no friction.” Evaluate the claim. State when it would be a useful idealization, name an omitted interaction and propose observations that would test whether its velocity remains constant. Explain a limit of your test.","guide":"With negligible net external force in an inertial frame, constant velocity and a straight path follow. Engine-off does not mean force-free: gravity may remain. Record positions/directions at known equal time intervals and compare displacement vectors or velocities, with measurement uncertainty and reference frame stated. A change beyond uncertainty challenges constant velocity; failure to detect change over a short interval does not prove zero force forever. Credit the conditional model, omitted force and a justified test with a limit.","points":3,"demand":{"blooms":"Evaluate","dok":3,"evidence":"Evaluates a force-free claim with a conditional model, evidence plan and uncertainty limitation."}}]}'::jsonb);
